require __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/admin_security.php';require_once __DIR__.'/../includes/admin_nav.php';require_once __DIR__.'/../includes/forum_storage.php';
kp_send_security_headers(true);header('Content-Type: text/html; charset=utf-8');$admin=kp_admin_require('/quan-tri/dang-nhap',['admin']);$csrf=kp_csrf_token();$error='';$notice='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{if(!kp_admin_csrf_valid($_POST['csrf']??null))throw new RuntimeException('Phiên bảo mật đã hết hạn.');if(($_POST['action']??'')!=='read_all')throw new RuntimeException('Thao tác không hợp lệ.');kp_db()->exec('UPDATE kp_admin_notifications SET is_read=1 WHERE is_read=0');$notice='Đã đọc hộp thư. Giao dịch chưa xử lý vẫn giữ chấm đỏ.';}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Không cập nhật được thông báo.';}}
$attention=kp_admin_attention_summary();$messages=[];$points=[];$banks=[];$forum=[];try{$db=kp_db();$messages=kp_admin_notifications($db,100);$points=$db->query(kp_points_sql("SELECT r.id,r.reward_title,r.points_cost,r.created_at,u.username FROM kp_points_redemptions r LEFT JOIN team_user u ON u.id=r.user_id WHERE r.status='pending' ORDER BY r.id ASC LIMIT 100"))->fetchAll(PDO::FETCH_ASSOC);$banks=$db->query("SELECT order_code,username,amount,status,created_at FROM kp_bank_orders WHERE status IN ('queued','paid_waiting_delivery','crediting','needs_review','wallet_crediting') ORDER BY id ASC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){kp_log('admin notification center query failed',$e);$error=$error?:'Một phần dữ liệu chưa tải được.';}
try{$forum=kp_db()->query(kp_forum_sql("SELECT id,title,kind,platform,created_at FROM kp_forum_topics WHERE status='new' ORDER BY id DESC LIMIT 100"))->fetchAll(PDO::FETCH_ASSOC);}
catch(Throwable $e){kp_log('admin forum notifications unavailable',$e);$error=$error?:'Không thể đọc các bài mới trên diễn đàn.';}
$cards=[];foreach(kp_topup_recent('orders',null,500) as $x)if(in_array((string)($x['status']??''),['submitting','verified_pending_delivery','queued','crediting','needs_review','wallet_crediting'],true))$cards[]=$x;$wallet=[];foreach(kp_vnd_recent_exchanges(null,500) as $x)if(in_array((string)($x['status']??''),['prepared','granting','needs_review'],true))$wallet[]=$x;
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Thông báo quản trị · KPAH</title><link rel="stylesheet" href="/assets/css/admin-home.css?v=<?=@filemtime(KP_ROOT.'/assets/css/admin-home.css')?>"><link rel="stylesheet" href="/assets/css/admin-nav.css?v=<?=@filemtime(KP_ROOT.'/assets/css/admin-nav.css')?>"><link rel="stylesheet" href="/assets/css/admin-theme.css?v=<?=@filemtime(KP_ROOT.'/assets/css/admin-theme.css')?>"><link rel="stylesheet" href="/assets/css/ui-system.css?v=<?=@filemtime(KP_ROOT.'/assets/css/ui-system.css')?>"><link rel="stylesheet" href="/assets/css/admin-notifications.css?v=<?=@filemtime(KP_ROOT.'/assets/css/admin-notifications.css')?>"></head><body><?php kp_admin_nav('notifications','admin');?><main class="shell admin-notice-shell"><section class="welcome admin-notice-hero"><div><div class="eyebrow">ADMIN / NOTIFICATIONS</div><h1>Trung tâm thông báo.</h1><p>Đọc inbox không thể che một đơn hoặc giao dịch vẫn chưa xử lý.</p></div><div class="admin-notice-total"><strong><?=$attention['total']?></strong><span>việc cần chú ý</span></div></section><?php if($error):?><div class="admin-notice-alert bad"><?=kp_e($error)?></div><?php endif;?><?php if($notice):?><div class="admin-notice-alert good"><?=kp_e($notice)?></div><?php endif;?><section class="admin-notice-metrics"><a href="#forum"><span>Diễn đàn</span><strong><?=$attention['forum']?></strong><small>Báo lỗi / góp ý mới</small></a><a href="#point"><span>Đổi quà</span><strong><?=$attention['points']?></strong><small>Chờ duyệt</small></a><a href="#bank"><span>Ngân hàng</span><strong><?=$attention['bank']?></strong><small>Queue / đối soát</small></a><a href="#card"><span>Thẻ cào</span><strong><?=$attention['cards']?></strong><small>Đang xử lý</small></a><a href="#wallet"><span>Đổi VNĐ</span><strong><?=$attention['wallet']?></strong><small>Cần xác minh</small></a></section>
<?php $sections=[['forum','Báo lỗi & góp ý mới','/quan-tri/forum',$forum,fn($x)=>'#'.$x['id'].' · '.$x['title'],fn($x)=>($x['kind']==='suggestion'?'Góp ý':'Báo lỗi').' · '.$x['platform']],['point','Đơn đổi quà chờ duyệt','/quan-tri/diem-tich-luy',$points,fn($x)=>'#'.$x['id'].' · '.$x['reward_title'],fn($x)=>($x['username']??'Tài khoản').' · '.number_format((int)$x['points_cost']).' Point'],['bank','Bank/PayOS queue hoặc đối soát','/quan-tri/doi-soat',$banks,fn($x)=>'#'.$x['order_code'].' · '.$x['status'],fn($x)=>$x['username'].' · '.number_format((int)$x['amount']).'đ'],['card','Đơn thẻ chưa kết thúc','/quan-tri/doi-soat',array_slice($cards,0,100),fn($x)=>'#'.strtoupper(substr((string)($x['id']??''),0,10)).' · '.($x['status']??''),fn($x)=>($x['username']??'').' · '.number_format((int)($x['amount']??0)).'đ'],['wallet','Lệnh đổi VNĐ cần kiểm tra','/quan-tri/doi-soat',array_slice($wallet,0,100),fn($x)=>'#'.strtoupper(substr((string)($x['id']??''),0,10)).' · '.($x['status']??''),fn($x)=>($x['username']??'Tài khoản').' · '.number_format((int)($x['amount_vnd']??0)).'đ']];?><section class="admin-notice-grid"><?php foreach($sections as [$id,$title,$url,$rows,$heading,$copy]):?><article class="admin-notice-panel" id="<?=kp_e($id)?>"><header><h2><?=kp_e($title)?></h2><a href="<?=kp_e($url)?>">Xử lý ↗</a></header><?php if(!$rows):?><p class="admin-notice-empty">Không có việc tồn.</p><?php else:?><div class="admin-notice-list"><?php foreach($rows as $x):?><a href="<?=kp_e($url)?>"><b><?=kp_e($heading($x))?></b><span><?=kp_e($copy($x))?></span></a><?php endforeach;?></div><?php endif;?></article><?php endforeach;?></section>
<section class="admin-notice-panel admin-notice-inbox"><header><h2>Hộp thư hệ thống</h2><?php if($messages):?><form method="post"><input type="hidden" name="csrf" value="<?=kp_e($csrf)?>"><input type="hidden" name="action" value="read_all"><button>Đánh dấu tất cả đã đọc</button></form><?php endif;?></header><?php if(!$messages):?><p class="admin-notice-empty">Chưa có thông báo.</p><?php else:?><div class="admin-notice-list"><?php foreach($messages as $x):?><a class="<?=!(int)$x['is_read']?'is-unread':''?>" href="<?=kp_admin_center_safe_path($x['link_path'])&&$x['link_path']!==''?kp_e($x['link_path']):'/quan-tri/thong-bao'?>"><b><?=kp_e($x['title'])?></b><span><?=kp_e($x['body'])?></span><small><?=kp_e($x['created_at'])?> · <?=!(int)$x['is_read']?'Chưa đọc':'Đã đọc'?></small></a><?php endforeach;?></div><?php endif;?></section></main></body></html>
